"""선택형 recipe 실행기 — 표준 경로로 자료를 받아 투영 CRS 정규 격자 표를 만들고 검증·provenance를 기록한다.

지원 범위: ESRI REST feature query(GeoJSON), WFS 2.0 GetFeature(JSON), WCS 2.x GetCoverage(GeoTIFF,
coverage의 native CRS와 축 이름으로 subset), 직접 파일과 사용자가 받은 로컬 파일 → 셀 단위 표. 열은
자료 값(value), 진단(diagnostic), 점 기록의 있음 표시·건수(record_derived), 영역 표시(mask)로 나뉜다.
원자료만 받는 작업, 격자가 아닌 산출물, 다른 서비스 형식은 assets를 조합한 별도 코드로 만든다.

이 스크립트는 흔한 경우를 재현 가능하게 돌리는 뼈대다. 포털마다 다른 접근 경로나 판단이 필요하면
에이전트가 assets를 직접 조합한 코드를 쓴다. 승인은 사용자가 명령행에서 명시할 때만 기록한다.
승인 전에는 어떤 host에도 요청(robots.txt 포함)을 보내지 않는다. 모든 다운로드와 redirect 단계는
승인한 host 안에서, 하나의 요청 예산으로 센다.

사용:
  uv run python skills/mpm-data-acquisition/scripts/acquire.py --recipe recipe.json --workspace WORK \
      [--approve-hosts --approved-by "<사용자>" --evidence "<승인 근거>" [--approval-scope "<현재 작업>"]] [--dry-run]

종료 코드: 0 성공(검증 error 없음) · 2 표는 만들었으나 검증 error · 3 승인 필요/예산 초과로 중단 · 1 기타 오류
"""
from __future__ import annotations

import argparse
import fnmatch
import json
import os
import re
import shutil
import sys
import zipfile
from datetime import datetime, timezone
from urllib.parse import quote, urlsplit

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(os.path.dirname(HERE), "assets"))

import downloader  # noqa: E402
import artifact_paths  # noqa: E402
import fetch_budget  # noqa: E402
import robots_gate  # noqa: E402

USER_AGENT = robots_gate.DEFAULT_USER_AGENT


def now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def log(msg: str) -> None:
    print(f"[acquire {datetime.now(timezone.utc).strftime('%H:%M:%S')}] {msg}", flush=True)


# ---------------------------------------------------------------------------
# host 승인
# ---------------------------------------------------------------------------
def hosts_of(recipe: dict) -> dict[str, str]:
    """host → 그 host에 실제로 보낼 URL 하나(scheme·port 보존). extra_hosts는 https 루트로 둔다."""
    hosts: dict[str, str] = {}
    for src in recipe.get("sources", {}).values():
        for key in ("url", "url_template"):
            if src.get(key):
                hosts.setdefault(robots_gate.host_of(src[key]), src[key])
    for h in recipe.get("extra_hosts", []):
        hosts.setdefault(h.lower(), f"https://{h}/")
    return dict(sorted(hosts.items()))


def check_consent(recipe: dict, workspace: str, budget: fetch_budget.FetchBudget, args, report: dict | None = None) -> dict:
    """Reuse or record user consent per host without sending any request.

    A saved robots observation (recon/<host>/robots.result.json) informs the user and its crawl-delay
    raises the request interval; this function never fetches robots.txt itself.
    """
    ledger = robots_gate.ConsentLedger(os.path.join(workspace, "consent-ledger.json"))
    report = {} if report is None else report
    for host, sample_url in hosts_of(recipe).items():
        paths = [urlsplit(src.get("url") or src.get("url_template") or "").path or "/"
                 for src in recipe["sources"].values()
                 if robots_gate.host_of(src.get("url") or src.get("url_template") or "https://x/") == host]
        if not paths:
            paths = [urlsplit(sample_url).path or "/"]
        if ledger.status(host) == "review_required":
            report[host] = {"status": "approval_required_review", "approval_reused": False}
            log(f"{host}: 원장에 review_required 표시가 있다. 과거 원장을 보존하고 실제 사용자 결정 근거를 확인한다.")
            continue
        try:
            rec = ledger.require(host, paths=paths, approval_scope=getattr(args, "approval_scope", ""),
                                 approved_by=getattr(args, "approved_by", ""))
        except robots_gate.ApprovalRequired:
            rec = None
        if rec is not None:
            report[host] = {"status": "approved", "approval_reused": True,
                            "robots_state": rec.get("robots_state"), "approved_at": rec.get("approved_at"),
                            "robots_disallowed_paths": rec.get("robots_disallowed_paths", [])}
            known = rec.get("last_present_robots")
            if known:
                budget.delay = max(budget.delay, robots_gate.crawl_delay(robots_gate.RobotsResult(**known)) or 0)
            continue
        result = robots_gate.cached_observation(workspace, sample_url)
        if args.approve_hosts:
            if not args.approved_by or not args.evidence:
                raise SystemExit("--approve-hosts에는 --approved-by와 --evidence가 필요하다")
            rec = ledger.record(host, result, approved_by=args.approved_by, paths=paths,
                                approval_scope=args.approval_scope, evidence=args.evidence,
                                note="Explicit user collection approval; robots advisory",
                                approve_disallowed=getattr(args, "approve_disallowed", False),
                                approve_unreadable=getattr(args, "approve_unreadable_robots", False))
            report[host] = {"status": "approved_now", "approval_reused": False,
                            "robots_state": result.state, "approved_at": rec["approved_at"],
                            "robots_disallowed_paths": rec["robots_disallowed_paths"]}
            budget.delay = max(budget.delay, robots_gate.crawl_delay(result) or 0)
            continue
        # No request is sent before approval, robots.txt included. A saved observation, if any, is shown.
        rec_dir = os.path.join(workspace, "recon", host)
        os.makedirs(rec_dir, exist_ok=True)
        summary = robots_gate.summarize(result, paths, USER_AGENT)
        with open(os.path.join(rec_dir, "robots.summary.txt"), "w", encoding="utf-8") as fh:
            fh.write("paths_relative_to: this file's directory\n" + summary + "\n")
        artifact_paths.dump_json(result.to_dict(), os.path.join(rec_dir, "robots.result.json"))
        report[host] = {"status": "approval_required", "robots_state": result.state,
                        "robots_disallowed_paths": ledger.disallowed_paths(host, result, paths)}
        print(summary)
    return report


# ---------------------------------------------------------------------------
# 다운로드
# ---------------------------------------------------------------------------
def _licence(src: dict) -> dict:
    lic = dict(src.get("licence") or {})
    lic.setdefault("verified", False)
    return lic


def _reuse(name: str, sig: str, index, reuse: bool, status: dict | None) -> str | None:
    """같은 요청 서명의 검증된 파일이 있으면 네트워크 없이 그 경로를 돌려준다."""
    if not reuse:
        return None
    path = index.verified_path(sig)
    if path:
        log(f"{name}: verified existing file reused (matching request signature; no network): {path}")
        if status is not None:
            status["reused"] = True
            status["request_signature"] = sig
    return path


def _numeric_count(value):
    if isinstance(value, bool) or value is None or str(value).strip().lower() == "unknown":
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _reported_count(data: dict, keys: tuple[str, ...]) -> int | None:
    for key in keys:
        value = data.get(key)
        if value is None and isinstance(data.get("properties"), dict):
            value = data["properties"].get(key)
        count = _numeric_count(value)
        if count is not None:
            return count
    return None


def _feature_identifier(feature: dict) -> str | None:
    if feature.get("id") is not None:
        return str(feature["id"])
    props = feature.get("properties") or {}
    for key in ("OBJECTID", "objectid", "ObjectID", "FID", "fid", "gml_id"):
        if props.get(key) is not None:
            return f"{key}:{props[key]}"
    return None


def _page_fingerprint(features: list) -> str:
    payload = json.dumps(features, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    return downloader.request_signature("feature_page", payload=payload)


def _accept_page(features: list, seen_pages: set[str], seen_ids: set[str], merged: list,
                 duplicate_ids: list[str]) -> bool:
    fingerprint = _page_fingerprint(features)
    if fingerprint in seen_pages:
        return True
    seen_pages.add(fingerprint)
    for feature in features:
        identifier = _feature_identifier(feature)
        if identifier is not None:
            if identifier in seen_ids:
                duplicate_ids.append(identifier)
                continue
            seen_ids.add(identifier)
        merged.append(feature)
    return False


def _paging_result(expected: int | None, received: int, stop_reason: str, duplicate_ids: list[str],
                   repeated_page: bool, server_signalled_more: bool = False) -> dict:
    if repeated_page or duplicate_ids or stop_reason in {"request_budget_exhausted", "max_features_reached",
                                                         "next_link_other_host", "empty_page_before_expected_count",
                                                         "server_count_inconsistent"}:
        completeness = "partial"
    elif expected is not None:
        completeness = "complete" if received >= expected and not server_signalled_more else "partial"
    elif stop_reason == "server_no_more_results":
        completeness = "complete"
    else:
        completeness = "unknown"
    warning = None if completeness == "complete" else (
        f"paging {completeness}: expected={expected}, received={received}, stop_reason={stop_reason}")
    return {"completeness": completeness, "expected_count": expected, "received_count": received,
            "stop_reason": stop_reason, "duplicate_ids": duplicate_ids, "repeated_page": repeated_page,
            "warning": warning}


def _response_crs(data: dict, src: dict, output_format: str) -> tuple[str, str]:
    crs_member = data.get("crs")
    name = None
    if isinstance(crs_member, dict):
        properties = crs_member.get("properties") or {}
        name = properties.get("name") or properties.get("href")
    name = name or data.get("srsName") or src.get("response_crs")
    if not name:
        fmt = output_format.lower()
        if "geo+json" in fmt or "geojson" in fmt:
            name = "EPSG:4326"  # RFC 7946 GeoJSON defaults to longitude/latitude.
        else:
            raise downloader.DownloadError(
                "WFS 응답 CRS를 확인할 수 없습니다. 응답 CRS 선언 또는 검증된 response_crs를 recipe에 제공하십시오.")
    try:
        from pyproj import CRS
        name = CRS.from_user_input(name).to_string()
    except Exception as exc:
        raise downloader.DownloadError(f"WFS 응답 CRS를 해석할 수 없습니다: {name!r}: {exc}") from exc
    axis_order = src.get("response_axis_order") or data.get("axisOrder")
    if axis_order is None:
        fmt = output_format.lower()
        if "geo+json" in fmt or "geojson" in fmt:
            axis_order = "xy"  # GeoJSON coordinates use x/y order.
        else:
            try:
                axis_order = _bbox_axis_order(name, None)
            except downloader.DownloadError as exc:
                raise downloader.DownloadError(
                    f"WFS 응답 축 순서를 확인할 수 없습니다. response_axis_order를 명시하십시오: {name}") from exc
    if axis_order not in {"xy", "yx"}:
        raise downloader.DownloadError(f"WFS 응답 축 순서를 확인할 수 없습니다: {axis_order!r}")
    return str(name), axis_order


def _bbox_axis_order(crs_name: str, configured: str | None) -> str:
    if configured:
        mapping = {"lonlat": "xy", "latlon": "yx", "xy": "xy", "yx": "yx"}
        if configured not in mapping:
            raise downloader.DownloadError(f"WFS bbox 축 순서를 확인할 수 없습니다: {configured!r}")
        return mapping[configured]
    try:
        from pyproj import CRS
        axes = CRS.from_user_input(crs_name).axis_info
    except Exception as exc:
        raise downloader.DownloadError(f"WFS bbox CRS 축 순서를 확인할 수 없습니다({crs_name!r}): {exc}") from exc
    if not axes:
        raise downloader.DownloadError(f"WFS bbox CRS 축 순서 정보가 없습니다: {crs_name!r}")
    first = (axes[0].direction or "").lower()
    if first in {"north", "south"}:
        return "yx"
    if first in {"east", "west"}:
        return "xy"
    raise downloader.DownloadError(f"WFS bbox 첫 축 방향을 확인할 수 없습니다: {first!r} ({crs_name})")


def _wfs_bbox(aoi_wgs84: list[float], crs_name: str, axis_order: str, densify: int = 256) -> str:
    """AOI bounds in the WFS bbox CRS from the densified AOI boundary (an approximation; see grid_table)."""
    import grid_table as gt

    try:
        bounds, _ = gt.bbox_bounds_in_crs(aoi_wgs84, crs_name, densify=densify)
    except Exception as exc:
        raise downloader.DownloadError(f"WFS bbox CRS 변환을 만들 수 없습니다(EPSG:4326 → {crs_name}): {exc}") from exc
    if axis_order == "yx":
        return f"{bounds[1]},{bounds[0]},{bounds[3]},{bounds[2]},{crs_name}"
    return f"{bounds[0]},{bounds[1]},{bounds[2]},{bounds[3]},{crs_name}"


def _transform_geojson_features(features: list, source_crs: str, target_crs: str,
                                axis_order: str = "xy") -> list:
    """Transform established source coordinates to the requested CRS; never infer a CRS transform."""
    from pyproj import CRS, Transformer
    from shapely.geometry import mapping, shape
    from shapely.ops import transform as transform_geometry

    try:
        source = CRS.from_user_input(source_crs)
        target = CRS.from_user_input(target_crs)
        transformer = Transformer.from_crs(source, target, always_xy=True)
    except Exception as exc:
        raise downloader.DownloadError(
            f"WFS CRS를 해석할 수 없습니다(source={source_crs!r}, target={target_crs!r}): {exc}") from exc

    def transform_xy(x, y, z=None):
        if axis_order == "yx":
            x, y = y, x
        return transformer.transform(x, y, z) if z is not None else transformer.transform(x, y)

    if source == target and axis_order == "xy":
        return features
    transformed = []
    for feature in features:
        item = dict(feature)
        geometry = feature.get("geometry")
        if geometry is not None:
            item["geometry"] = mapping(transform_geometry(transform_xy, shape(geometry)))
        transformed.append(item)
    return transformed


def _next_link(data: dict) -> str | None:
    direct = data.get("next")
    if isinstance(direct, str):
        return direct
    for link in data.get("links", []) or []:
        if isinstance(link, dict) and str(link.get("rel", "")).lower() == "next" and link.get("href"):
            return str(link["href"])
    return None


def _source_hosts(src: dict, allowed_hosts) -> set[str]:
    """Hosts a source request may reach: the caller's approved list, or only the source URL's own host."""
    if allowed_hosts is not None:
        return downloader.normalise_hosts(allowed_hosts)
    return {robots_gate.host_of(src["url"])}


def esri_page_size(src: dict) -> int:
    """Requested page size: `page_size` (default 1000), capped by a known service `max_record_count`.

    A server returns at most its own maxRecordCount per page and signals more with
    exceededTransferLimit; paging continues on that signal whatever page size was asked for.
    """
    page = int(src.get("page_size", 1000))
    known = src.get("max_record_count")
    return min(page, int(known)) if known else page


def fetch_esri_query(name: str, src: dict, aoi: list[float], raw_dir: str, budget, index,
                     reuse: bool = True, status: dict | None = None, allowed_hosts=None) -> str:
    west, south, east, north = aoi
    hosts = _source_hosts(src, allowed_hosts)
    page = esri_page_size(src)
    max_features = int(src.get("max_features", 50_000))
    where = src.get("where", "1=1")
    out_fields = src.get("out_fields", "*")
    sig = downloader.request_signature("esri_query", url=src["url"], where=where, out_fields=out_fields, aoi=aoi,
                                       page_size=page, max_features=max_features)
    cached = _reuse(name, sig, index, reuse, status)
    if cached:
        rec = index.by_signature(sig) or {}
        if status is not None:
            status["paging"] = {k: rec.get(k) for k in (
                "completeness", "expected_count", "received_count", "stop_reason", "duplicate_ids",
                "repeated_page", "warning")}
        return cached
    features: list = []
    pages = []
    offset = 0
    received = 0
    expected = _numeric_count(src.get("expected_count"))
    duplicate_ids: list[str] = []
    seen_ids: set[str] = set()
    seen_pages: set[str] = set()
    repeated_page = False
    server_signalled_more = False
    stop_reason = "unknown"
    while True:
        if received >= max_features:
            stop_reason = "max_features_reached"
            break
        request_page = min(page, max_features - received)
        url = (f"{src['url'].rstrip('/')}/query?where={quote(where)}&outFields={quote(out_fields)}"
               f"&geometry={west},{south},{east},{north}&geometryType=esriGeometryEnvelope&inSR=4326"
               f"&spatialRel=esriSpatialRelIntersects&outSR=4326&returnGeometry=true&f=geojson"
               f"&resultOffset={offset}&resultRecordCount={request_page}")
        dest = os.path.join(raw_dir, name, f"page_{offset:06d}.geojson")
        try:
            rec = downloader.download(url, dest, budget=budget, user_agent=USER_AGENT, licence=_licence(src),
                                      source=src.get("record", {}), overwrite=True,
                                      max_bytes=int(src.get("max_bytes", 200_000_000)),
                                      request_signature=f"{sig}:page:{offset}", allowed_hosts=hosts)
        except fetch_budget.BudgetExceeded:
            stop_reason = "request_budget_exhausted"
            break
        index.add(rec)
        pages.append(rec)
        with open(dest, encoding="utf-8") as fh:
            data = json.load(fh)
        if "error" in data:
            raise downloader.DownloadError(f"ESRI error for {name}: {data['error']}")
        got = data.get("features", [])
        reported = _reported_count(data, ("totalFeatures", "numberMatched", "count"))
        if reported is not None:
            expected = reported
        repeated_page = _accept_page(got, seen_pages, seen_ids, features, duplicate_ids)
        received += len(got)
        more = bool(data.get("exceededTransferLimit")) or (data.get("properties") or {}).get("exceededTransferLimit")
        server_signalled_more = bool(more)
        if repeated_page:
            stop_reason = "repeated_page"
            break
        if not got:
            stop_reason = "empty_page_before_expected_count" if expected is not None and received < expected else "server_no_more_results"
            break
        offset += len(got)
        if expected is not None and received >= expected and not more:
            stop_reason = "expected_count_reached"
            break
        if len(got) < request_page and not more:
            stop_reason = "server_no_more_results"
            break
    paging = _paging_result(expected, received, stop_reason, duplicate_ids, repeated_page, server_signalled_more)
    merged = os.path.join(raw_dir, f"{name}.geojson")
    with open(merged, "w", encoding="utf-8") as fh:
        json.dump({"paths_relative_to": "this file's directory", "type": "FeatureCollection", "features": features,
                   "_provenance": {"pages": [p["sha256"] for p in pages], "n_features": len(features), **paging}}, fh)
    merged_provenance = {"merged_from_pages": [p["path"] for p in pages], "sha256": downloader.sha256_file(merged),
                         "path": os.path.abspath(merged), "page_sha256": [p["sha256"] for p in pages],
                         "n_features": len(features), "licence": _licence(src), "source": src.get("record", {}),
                         "retrieved_at": now(), "request_signature": sig, **paging}
    downloader.write_provenance(merged_provenance, merged + ".provenance.json")
    index.add(merged_provenance)
    if status is not None:
        status["request_signature"] = sig
        status["paging"] = paging
    log(f"{name}: {len(features)} features in {len(pages)} page(s); paging={paging['completeness']} "
        f"expected={expected} received={received} stop={stop_reason}")
    return merged


def fetch_wfs(name: str, src: dict, aoi: list[float], raw_dir: str, budget, index,
              reuse: bool = True, status: dict | None = None, allowed_hosts=None) -> str:
    hosts = _source_hosts(src, allowed_hosts)
    bbox_crs = src.get("bbox_srs", src.get("srs", "EPSG:4326"))
    bbox_axis = _bbox_axis_order(bbox_crs, src.get("bbox_axis_order"))
    bbox = _wfs_bbox(aoi, bbox_crs, bbox_axis, densify=int(src.get("boundary_densify", 256)))
    target_crs = src.get("target_srs", src.get("output_srs", src.get("srs", "EPSG:4326")))
    page = int(src.get("page_size", 1000))
    max_features = int(src.get("max_features", 50_000))
    output_format = src.get("output_format", "application/json")
    sig = downloader.request_signature("wfs_getfeature", url=src["url"], type_name=src["type_name"], bbox=bbox,
                                       output_format=output_format, target_crs=target_crs,
                                       cql_filter=src.get("cql_filter"), page_size=page,
                                       max_features=max_features)
    cached = _reuse(name, sig, index, reuse, status)
    if cached:
        rec = index.by_signature(sig) or {}
        if status is not None:
            status["paging"] = {k: rec.get(k) for k in (
                "completeness", "expected_count", "received_count", "stop_reason", "duplicate_ids",
                "repeated_page", "warning")}
        return cached
    features: list = []
    pages = []
    start = 0
    received = 0
    expected = _numeric_count(src.get("expected_count"))
    duplicate_ids: list[str] = []
    seen_ids: set[str] = set()
    seen_pages: set[str] = set()
    seen_urls: set[str] = set()
    repeated_page = False
    server_signalled_more = False
    stop_reason = "unknown"
    response_crs = None
    response_axis = None
    current_url = None
    while True:
        if received >= max_features:
            stop_reason = "max_features_reached"
            break
        request_page = min(page, max_features - received)
        if current_url is None:
            url = (f"{src['url']}?service=WFS&version=2.0.0&request=GetFeature&typeNames={quote(src['type_name'])}"
                   f"&outputFormat={quote(output_format)}&bbox={quote(bbox, safe=',:')}"
                   f"&srsName={quote(target_crs, safe=':')}&count={request_page}&startIndex={start}")
            if src.get("cql_filter"):
                url += f"&cql_filter={quote(src['cql_filter'])}"
        else:
            url = current_url
        if url in seen_urls:
            stop_reason = "repeated_page"
            repeated_page = True
            break
        seen_urls.add(url)
        dest = os.path.join(raw_dir, name, f"page_{received:06d}.geojson")
        try:
            rec = downloader.download(url, dest, budget=budget, user_agent=USER_AGENT, licence=_licence(src),
                                      source=src.get("record", {}), overwrite=True,
                                      max_bytes=int(src.get("max_bytes", 200_000_000)),
                                      request_signature=f"{sig}:page:{received}", allowed_hosts=hosts)
        except fetch_budget.BudgetExceeded:
            stop_reason = "request_budget_exhausted"
            break
        index.add(rec)
        pages.append(rec)
        with open(dest, encoding="utf-8") as fh:
            head = fh.read(200)
        if head.lstrip().startswith("<"):
            raise downloader.DownloadError(f"WFS returned XML (exception?) for {name}: {head[:120]}")
        with open(dest, encoding="utf-8") as fh:
            data = json.load(fh)
        got = data.get("features", [])
        declared_crs, declared_axis = _response_crs(data, src, output_format)
        if response_crs is None:
            response_crs, response_axis = declared_crs, declared_axis
        elif response_crs != declared_crs or response_axis != declared_axis:
            raise downloader.DownloadError(
                f"WFS 페이지별 CRS/축 순서가 다릅니다: {response_crs}/{response_axis} vs {declared_crs}/{declared_axis}")
        got = _transform_geojson_features(got, response_crs, target_crs, response_axis)
        reported = _reported_count(data, ("numberMatched",))
        if reported is not None:
            expected = reported
        number_returned = _reported_count(data, ("numberReturned",))
        repeated_page = _accept_page(got, seen_pages, seen_ids, features, duplicate_ids)
        received += len(got)
        matched = expected
        next_href = _next_link(data)
        server_signalled_more = bool(next_href) or (expected is not None and received < expected)
        if repeated_page:
            stop_reason = "repeated_page"
            break
        if number_returned is not None and number_returned != len(data.get("features", [])):
            stop_reason = "server_count_inconsistent"
            break
        if expected is not None and received >= expected:
            stop_reason = "expected_count_reached"
            break
        if next_href:
            from urllib.parse import urljoin
            next_url = urljoin(url, next_href)
            if urlsplit(next_url).netloc.lower() != urlsplit(src["url"]).netloc.lower():
                stop_reason = "next_link_other_host"
                break
            current_url = next_url
            start += len(got)
            continue
        if not got:
            stop_reason = "empty_page_before_expected_count" if expected is not None and received < expected else "server_no_more_results"
            break
        if len(got) < request_page:
            stop_reason = "empty_page_before_expected_count" if expected is not None and received < expected else "server_no_more_results"
            break
        start += len(got)
        current_url = None
    paging = _paging_result(expected, received, stop_reason, duplicate_ids, repeated_page, server_signalled_more)
    if response_crs is None:
        raise downloader.DownloadError(f"WFS에서 {name} 자료의 응답 CRS를 확인하지 못했습니다.")
    merged = os.path.join(raw_dir, f"{name}.geojson")
    with open(merged, "w", encoding="utf-8") as fh:
        json.dump({"paths_relative_to": "this file's directory", "type": "FeatureCollection",
                   "crs": {"type": "name", "properties": {"name": target_crs}}, "features": features,
                   "_provenance": {"pages": [p["sha256"] for p in pages], "n_features": len(features),
                                   "numberMatched": matched, **paging}}, fh)
    merged_provenance = {"merged_from_pages": [p["path"] for p in pages], "sha256": downloader.sha256_file(merged),
                         "path": os.path.abspath(merged), "page_sha256": [p["sha256"] for p in pages],
                         "n_features": len(features), "numberMatched": matched,
                         "bbox_crs": bbox_crs, "source_crs": response_crs, "target_crs": target_crs,
                         "response_axis_order": response_axis, "licence": _licence(src),
                         "source": src.get("record", {}), "retrieved_at": now(), "request_signature": sig, **paging}
    downloader.write_provenance(merged_provenance, merged + ".provenance.json")
    index.add(merged_provenance)
    if status is not None:
        status["request_signature"] = sig
        status["paging"] = paging
    log(f"{name}: {len(features)} features; numberMatched={matched}; paging={paging['completeness']} "
        f"expected={expected} received={received} stop={stop_reason}")
    return merged


WCS_TIFF_FORMATS = {"image/tiff", "image/geotiff", "image/tiff;application=geotiff"}


def wcs_subset(aoi_wgs84: list[float], src: dict) -> dict:
    """AOI(+query_buffer_deg) bounds in the coverage's native CRS, keyed by the coverage's axis labels.

    WCS 2.x core reads subset coordinates in the coverage's native CRS. The recipe states that CRS
    (`subset_crs`) and the labels of its easting/longitude and northing/latitude axes
    (`axes: {"x": ..., "y": ...}`), both taken from DescribeCoverage for the current service.
    """
    import grid_table as gt

    axes = src["axes"]
    (minx, miny, maxx, maxy), info = gt.bbox_bounds_in_crs(query_bbox(aoi_wgs84, src), src["subset_crs"],
                                                           densify=int(src.get("boundary_densify", 256)))
    return {"x_axis": axes["x"], "y_axis": axes["y"], "x": [minx, maxx], "y": [miny, maxy],
            "subset_crs": src["subset_crs"], "bounds_method": info}


def fetch_wcs(name: str, src: dict, aoi: list[float], raw_dir: str, budget, index,
              reuse: bool = True, status: dict | None = None, allowed_hosts=None) -> str:
    sub = wcs_subset(aoi, src)
    fmt = src.get("format", "image/tiff")
    url = (f"{src['url']}?service=WCS&version={src.get('version', '2.0.1')}&request=GetCoverage"
           f"&coverageId={quote(src['coverage_id'])}"
           f"&subset={quote(sub['x_axis'])}({sub['x'][0]!r},{sub['x'][1]!r})"
           f"&subset={quote(sub['y_axis'])}({sub['y'][0]!r},{sub['y'][1]!r})"
           f"&format={quote(fmt)}")
    sig = downloader.request_signature("wcs_getcoverage", url=url)
    cached = _reuse(name, sig, index, reuse, status)
    if cached:
        return cached
    dest = os.path.join(raw_dir, f"{name}.tif")
    rec = downloader.download(url, dest, budget=budget, user_agent=USER_AGENT, licence=_licence(src),
                              source=src.get("record", {}), overwrite=True,
                              max_bytes=int(src.get("max_bytes", 300_000_000)), request_signature=sig,
                              allowed_hosts=_source_hosts(src, allowed_hosts))
    if "tiff" not in (rec.get("content_type") or "").lower():
        with open(dest, "rb") as fh:
            head = fh.read(300)
        raise downloader.DownloadError(f"WCS did not return TIFF for {name}: {rec.get('content_type')} {head[:120]!r}")
    rec["wcs_subset"] = sub
    index.add(rec)
    if status is not None:
        status["request_signature"] = sig
    log(f"{name}: {rec['bytes']} bytes GeoTIFF")
    return dest


def fetch_file(name: str, src: dict, raw_dir: str, budget, index, reuse: bool = True,
               status: dict | None = None, allowed_hosts=None) -> list[str]:
    ext = os.path.splitext(urlsplit(src["url"]).path)[1] or ".bin"
    dest = os.path.join(raw_dir, f"{name}{ext}")
    sig = downloader.request_signature("file", url=src["url"])
    cached = _reuse(name, sig, index, reuse, status)
    if cached:
        return _select_files(cached, src, raw_dir, name)
    rec = downloader.download(src["url"], dest, budget=budget, user_agent=USER_AGENT, licence=_licence(src),
                              source=src.get("record", {}), overwrite=True,
                              max_bytes=int(src.get("max_bytes", 500_000_000)), request_signature=sig,
                              allowed_hosts=_source_hosts(src, allowed_hosts))
    index.add(rec)
    if status is not None:
        status["request_signature"] = sig
    return _select_files(dest, src, raw_dir, name)


def local_file(name: str, src: dict, raw_dir: str, index) -> list[str]:
    """사용자가 직접(예: 브라우저로) 받은 파일. 출처 URL·라이선스는 recipe에 적힌 대로 기록한다."""
    path = src["path"]
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    rec = {"schema_version": 1, "url": src.get("url"), "final_url": None, "http_status": None, "content_type": None,
           "bytes": os.path.getsize(path), "sha256": downloader.sha256_file(path), "retrieved_at": now(),
           "user_agent": None, "path": os.path.abspath(path), "licence": _licence(src), "source": src.get("record", {}),
           "note": "local_file: obtained by the user outside this script"}
    downloader.write_provenance(rec, os.path.join(raw_dir, f"{name}.local.provenance.json"))
    index.add(rec)
    return _select_files(path, src, raw_dir, name)


def _select_files(path: str, src: dict, raw_dir: str, name: str) -> list[str]:
    if src.get("unzip") and zipfile.is_zipfile(path):
        out = os.path.join(raw_dir, name)
        os.makedirs(out, exist_ok=True)
        with zipfile.ZipFile(path) as zf:
            for member in zf.infolist():
                target = os.path.realpath(os.path.join(out, member.filename))
                if not target.startswith(os.path.realpath(out) + os.sep):
                    raise ValueError(f"zip path traversal: {member.filename}")
            zf.extractall(out)
        files = [os.path.join(r, f) for r, _, fs in os.walk(out) for f in fs]
    else:
        files = [path]
    pattern = src.get("select")
    if pattern:
        files = [f for f in files if fnmatch.fnmatch(os.path.basename(f), pattern)]
    return sorted(files)


