def _match(props: dict, rule: dict | None) -> bool:
    if not rule:
        return True
    property_name = rule.get("property")
    if not property_name:
        raise ValueError(f"predicate.property가 없다: {rule}")
    val = props.get(property_name)
    sval = "" if val is None else str(val)
    if "equals" in rule:
        return sval == str(rule["equals"])
    if "contains" in rule:
        return str(rule["contains"]) in sval
    if "in" in rule:
        return sval in {str(v) for v in rule["in"]}
    if "regex" in rule:
        return re.search(rule["regex"], sval) is not None
    raise ValueError(f"알 수 없는 filter: {rule}")


FEATURE_TYPES = {"raster", "distance", "polygon_attribute", "polygon_fraction", "line_density", "point_statistic",
                 "point_presence"}
USER_ROLES = {"value", "diagnostic"}
POINT_RULES = {"centroid", "representative_point"}


def default_role(feat: dict) -> str:
    """Column role when the recipe gives none: record-derived for presence, diagnostic for sample counts."""
    if feat.get("type") == "point_presence":
        return "record_derived"
    if feat.get("type") == "point_statistic" and feat.get("stat") == "count":
        return "diagnostic"
    return "value"


def derived_columns(feat: dict, recipe: dict) -> list[str]:
    """Names of the extra columns a feature adds next to its own column."""
    name = feat.get("name")
    extra = []
    if feat.get("type") == "point_presence":
        extra.append(f"{name}_count")
    if feat.get("fill"):
        extra.append(f"{name}_support_distance")
    source = (recipe.get("sources") or {}).get(feat.get("source")) or {}
    if feat.get("type") == "distance" and source.get("type") in ("esri_query", "wfs_getfeature"):
        extra.append(f"{name}_edge_limited")
    return extra


def validate_recipe(recipe: dict) -> list[str]:
    """자리표시자·형식 오류를 네트워크 접근 전에 잡는다."""
    problems = []
    if "label" in recipe:
        problems.append("최상위 label 블록은 쓰지 않는다: 점 기록의 있음 표시는 features에 "
                        "type=point_presence로 적는다")
    if "min_features" in (recipe.get("requirements") or {}):
        problems.append("requirements.min_features는 쓰지 않는다: 요청한 열은 모두 만들어져야 하며 빠지면 오류로 보고한다")
    mmf = (recipe.get("requirements") or {}).get("max_missing_fraction")
    if mmf is not None and (isinstance(mmf, bool) or not isinstance(mmf, (int, float)) or not 0 <= mmf <= 1):
        problems.append("requirements.max_missing_fraction은 0–1 숫자여야 한다")
    aoi = recipe.get("aoi_wgs84")
    if not (isinstance(aoi, list) and len(aoi) == 4 and all(isinstance(v, (int, float)) for v in aoi)):
        problems.append(f"aoi_wgs84는 숫자 4개(west, south, east, north)여야 한다: {aoi!r}")
    elif not (aoi[0] < aoi[2] and aoi[1] < aoi[3]):
        problems.append(f"aoi_wgs84 순서가 잘못됐다(west<east, south<north): {aoi}")
    g = recipe.get("grid") or {}
    for k in ("crs", "cell_size"):
        if k not in g:
            problems.append(f"grid.{k} 없음")
    if not g.get("from_aoi") and not all(k in g for k in ("minx", "miny", "maxx", "maxy")):
        problems.append("grid 경계(minx/miny/maxx/maxy)가 없으면 grid.from_aoi=true를 지정한다")
    b = recipe.get("budget") or {}
    for key in ("max_requests", "max_seconds"):
        v = b.get(key)
        if v is not None and (isinstance(v, bool) or not isinstance(v, (int, float)) or v <= 0):
            problems.append(f"budget.{key}는 양수여야 한다")
    for name, src in (recipe.get("sources") or {}).items():
        required = {"esri_query": ["url"], "wfs_getfeature": ["url", "type_name"],
                    "wcs_getcoverage": ["url", "coverage_id", "subset_crs", "axes"], "file": ["url"],
                    "local_file": ["path"]}
        if src.get("type") not in required:
            problems.append(f"source {name}: 지원하지 않거나 누락된 type")
        else:
            for key in required[src["type"]]:
                if not src.get(key):
                    problems.append(f"source {name}.{key} 없음")
        for key in ("url", "url_template", "path"):
            v = src.get(key)
            if isinstance(v, str) and ("<" in v or ">" in v):
                problems.append(f"source {name}.{key}에 자리표시자가 남아 있다: {v}")
        buffer = src.get("query_buffer_deg")
        if buffer is not None and (isinstance(buffer, bool) or not isinstance(buffer, (int, float)) or buffer < 0):
            problems.append(f"source {name}.query_buffer_deg는 0 이상의 숫자(도)여야 한다")
        if src.get("type") == "esri_query":
            if "where" in src and (not isinstance(src["where"], str) or not src["where"].strip()):
                problems.append(f"source {name}.where는 비어 있지 않은 문자열이어야 한다")
            if "out_fields" in src and (not isinstance(src["out_fields"], str) or not src["out_fields"].strip()):
                problems.append(f"source {name}.out_fields는 '*' 또는 필드 목록이어야 한다")
            for key in ("page_size", "max_record_count"):
                v = src.get(key)
                if key in src and (isinstance(v, bool) or not isinstance(v, int) or v < 1):
                    problems.append(f"source {name}.{key}는 양의 정수여야 한다")
        if src.get("type") == "wcs_getcoverage":
            if "margin_deg" in src:
                problems.append(f"source {name}.margin_deg는 쓰지 않는다: AOI 확장은 query_buffer_deg로 적는다")
            axes = src.get("axes")
            if axes and not (isinstance(axes, dict) and isinstance(axes.get("x"), str) and axes.get("x")
                             and isinstance(axes.get("y"), str) and axes.get("y")):
                problems.append(f"source {name}.axes는 DescribeCoverage의 축 이름 {{\"x\": 동·경도 축, \"y\": 북·위도 축}}이어야 한다")
            if src.get("subset_crs"):
                try:
                    from pyproj import CRS
                    CRS.from_user_input(src["subset_crs"])
                except Exception:
                    problems.append(f"source {name}.subset_crs를 해석할 수 없다: {src['subset_crs']!r}")
            fmt = str(src.get("format", "image/tiff")).lower().replace(" ", "")
            if fmt not in WCS_TIFF_FORMATS:
                problems.append(f"source {name}.format: 이 실행기는 GeoTIFF 응답만 지원한다({sorted(WCS_TIFF_FORMATS)})")
    names_seen = []
    for f in recipe.get("features") or []:
        ftype = f.get("type")
        if ftype not in FEATURE_TYPES:
            problems.append(f"feature {f.get('name')}: 지원하지 않거나 누락된 type")
        if ftype in {"polygon_attribute", "polygon_fraction", "point_statistic"} and not f.get("property"):
            problems.append(f"feature {f.get('name')}.property 없음")
        expected_unit = {"polygon_fraction": "fraction", "line_density": "km/km2"}.get(ftype)
        if expected_unit and f.get("unit", expected_unit) != expected_unit:
            problems.append(f"feature {f.get('name')}.unit은 {expected_unit}여야 한다")
        predicate = f.get("predicate", f.get("filter"))
        if ftype == "polygon_fraction" and not predicate:
            problems.append(f"feature {f.get('name')}.predicate가 필요하다(대상 범주를 명시한다)")
        if predicate is not None:
            if not isinstance(predicate, dict) or not predicate.get("property"):
                problems.append(f"feature {f.get('name')}.predicate는 property와 비교 규칙을 가진 객체여야 한다")
            elif sum(k in predicate for k in ("equals", "contains", "in", "regex")) != 1:
                problems.append(f"feature {f.get('name')}.predicate에는 equals|contains|in|regex 중 하나가 필요하다")
            elif "regex" in predicate:
                try:
                    re.compile(str(predicate["regex"]))
                except re.error as exc:
                    problems.append(f"feature {f.get('name')}.predicate.regex가 잘못됐다: {exc}")
        if ftype == "point_presence":
            if "role" in f and f["role"] != "record_derived":
                problems.append(f"feature {f.get('name')}.role: point_presence 열의 역할은 record_derived로 고정이다")
            buf = f.get("buffer", 0)
            if isinstance(buf, bool) or not isinstance(buf, (int, float)) or buf < 0:
                problems.append(f"feature {f.get('name')}.buffer는 0 이상의 숫자(격자 CRS 단위)여야 한다")
        elif "role" in f and f["role"] not in USER_ROLES:
            problems.append(f"feature {f.get('name')}.role은 value|diagnostic 중 하나여야 한다")
        if "point_rule" in f and (ftype not in {"point_statistic", "point_presence"} or f["point_rule"] not in POINT_RULES):
            problems.append(f"feature {f.get('name')}.point_rule은 point_statistic·point_presence에서 "
                            f"{sorted(POINT_RULES)} 중 하나로만 쓴다")
        fill = f.get("fill")
        if fill is not None:
            if f.get("type") != "point_statistic":
                problems.append(f"feature {f.get('name')}: fill은 point_statistic에만 쓴다")
            md = fill.get("max_distance") if isinstance(fill, dict) else None
            if not isinstance(md, (int, float)) or isinstance(md, bool) or md <= 0:
                problems.append(f"feature {f.get('name')}.fill.max_distance는 양수여야 한다(무제한 외삽 금지)")
        if isinstance(f.get("file"), str) and ("<" in f["file"] or ">" in f["file"]):
            problems.append(f"feature {f.get('name')}.file에 자리표시자가 남아 있다")
        if f.get("source") not in (recipe.get("sources") or {}):
            problems.append(f"feature {f.get('name')}의 source가 없다: {f.get('source')}")
        names_seen += [f.get("name"), *derived_columns(f, recipe)]
    handoff = (recipe.get("output") or {}).get("handoff", "aoi_centre")
    if handoff not in {"aoi_centre", "full_grid"}:
        problems.append("output.handoff는 aoi_centre|full_grid 중 하나여야 한다")
    names = [g.get("x_column", "x"), g.get("y_column", "y"), *names_seen]
    reserved = {"cell_id", "row", "col", "in_aoi"}
    if any(not isinstance(n, str) or not n or n in reserved for n in names) or len(set(names)) != len(names):
        problems.append("좌표·feature 열 이름(파생 열 포함)은 필수·고유하며 cell_id/row/col/in_aoi와 충돌할 수 없다")
    return problems


def query_bbox(aoi_wgs84: list[float], src: dict) -> list[float]:
    """Source query bbox: the AOI widened by the source's optional `query_buffer_deg` (degrees, >= 0)."""
    buffer = float(src.get("query_buffer_deg") or 0.0)
    west, south, east, north = map(float, aoi_wgs84)
    return [max(west - buffer, -180.0), max(south - buffer, -90.0), min(east + buffer, 180.0), min(north + buffer, 90.0)]


def grid_bounds_from_aoi(aoi_wgs84: list[float], crs: str, cell_size: float, densify: int = 256) -> dict:
    """WGS84 bbox(west, south, east, north)를 격자 CRS로 옮겨 셀 크기 배수로 넓힌 경계.

    경계는 촘촘히 나눈 AOI 경계를 투영한 근사이며(`grid_table.bbox_bounds_in_crs`), 근사 방법과
    추정 편차를 `bounds_method`에 남긴다.
    """
    import math
    import grid_table as gt

    (minx, miny, maxx, maxy), info = gt.bbox_bounds_in_crs(aoi_wgs84, crs, densify=densify)
    return {"minx": math.floor(minx / cell_size) * cell_size, "miny": math.floor(miny / cell_size) * cell_size,
            "maxx": math.ceil(maxx / cell_size) * cell_size, "maxy": math.ceil(maxy / cell_size) * cell_size,
            "bounds_method": info}


def _as_points(geoms: list, feat: dict) -> tuple[list, str | None]:
    """Point geometries for point features. Other geometries need an explicit `point_rule`."""
    if all(g.geom_type == "Point" for g in geoms):
        return list(geoms), None
    rule = feat.get("point_rule")
    if rule == "centroid":
        return [g if g.geom_type == "Point" else g.centroid for g in geoms], rule
    if rule == "representative_point":
        return [g if g.geom_type == "Point" else g.representative_point() for g in geoms], rule
    kinds = sorted({g.geom_type for g in geoms if g.geom_type != "Point"})
    raise ValueError(f"{feat['name']}: point가 아닌 geometry {kinds}가 있다. 바꾸는 규칙을 "
                     f"point_rule(centroid|representative_point)로 명시한다")


def build_table(recipe: dict, files: dict[str, list[str]], workspace: str, index,
                source_completeness: dict | None = None) -> tuple[dict, int]:
    import numpy as np
    import pandas as pd
    import grid_table as gt

    g = dict(recipe["grid"])
    bounds_method = None
    if g.get("from_aoi") or not all(k in g for k in ("minx", "miny", "maxx", "maxy")):
        bounds = grid_bounds_from_aoi(recipe["aoi_wgs84"], g["crs"], float(g["cell_size"]),
                                      densify=int(g.get("boundary_densify", 256)))
        bounds_method = bounds.pop("bounds_method")
        g.update(bounds)
        log(f"grid bounds from aoi_wgs84: {[g[k] for k in ('minx', 'miny', 'maxx', 'maxy')]} ({g['crs']}, cell {g['cell_size']})")
    spec = gt.GridSpec(crs=g["crs"], cell_size=g["cell_size"], minx=g["minx"], miny=g["miny"], maxx=g["maxx"],
                       maxy=g["maxy"], x_column=g.get("x_column", "x"), y_column=g.get("y_column", "y"))
    grid = gt.build_grid(spec)
    columns: dict[str, dict] = {}                 # every data column with its role
    values: dict[str, np.ndarray] = {}            # float columns in table order
    extra: dict[str, np.ndarray] = {}             # presence/count columns kept as integers
    units: dict[str, str] = {}
    vectors_cache: dict[str, tuple] = {}
    dropped: list[dict] = []

    def vector(source_name: str):
        if source_name not in vectors_cache:
            geoms, props, crs = gt.read_geojson(files[source_name][0])
            vectors_cache[source_name] = (gt.to_grid_crs(geoms, crs, spec), props, crs)
        return vectors_cache[source_name]

    for feat in recipe["features"]:
        name, ftype, source = feat["name"], feat["type"], feat["source"]
        role = feat.get("role") or default_role(feat)
        src_files = files.get(source, [])
        prov = index.by_sha(downloader.sha256_file(src_files[0])) if src_files else None
        col = {"definition": feat.get("definition", ""), "unit": feat.get("unit", "unknown"),
               "unit_basis": feat.get("unit_basis") or ("unconfirmed" if feat.get("unit", "unknown") == "unknown"
                                                         else "unconfirmed: stated in the recipe without a cited basis"),
               "type": ftype, "role": role,
               "source": source, "source_files": src_files, "source_sha256": prov["sha256"] if prov else None,
               "licence": (recipe["sources"][source].get("licence") or {}), "record": recipe["sources"][source].get("record", {})}
        source_spec = recipe["sources"][source]
        if source_spec.get("type") == "esri_query":
            col["source_query"] = {"where": source_spec.get("where", "1=1"),
                                   "out_fields": source_spec.get("out_fields", "*"),
                                   "page_size": esri_page_size(source_spec)}
        predicate = feat.get("predicate", feat.get("filter"))
        if predicate is not None:
            col["predicate"] = predicate
        extra_cols: dict[str, tuple[np.ndarray, dict]] = {}
        integer_column = False
        if ftype == "raster":
            path = feat.get("file") or (src_files[0] if len(src_files) == 1 else None)
            if path is None:
                raise ValueError(f"{name}: raster 파일이 여러 개다. 'file'로 지정한다: {src_files}")
            column, info = gt.sample_raster(spec, path, band=int(feat.get("band", 1)), method=feat.get("method", "mean"),
                                            src_nodata=feat.get("nodata"))
            col["sampling"] = info
            col["source_sha256"] = downloader.sha256_file(path)
        elif ftype == "distance":
            geoms, props, _ = vector(source)
            if predicate:
                geoms, props = gt.filter_features(geoms, props, lambda p: _match(p, predicate))
            if len(geoms) == 0:
                log(f"{name}: AOI 안에 feature가 0개라 열을 만들지 않는다")
                dropped.append({"feature": name, "reason": "0 features in AOI after filter"})
                continue
            column = gt.distance_to_features(spec, geoms, grid)
            col["unit"] = spec.unit
            col["unit_basis"] = f"computed in the grid CRS {spec.crs}; axis unit {spec.unit}"
            if source_spec.get("type") in ("esri_query", "wfs_getfeature"):
                limited, edge_info = gt.distance_edge_limited(spec, column, query_bbox(recipe["aoi_wgs84"], source_spec),
                                                              grid, densify=int(g.get("boundary_densify", 256)))
                extra_cols[f"{name}_edge_limited"] = (limited.astype(float), {
                    "definition": (f"1 where {name} may be overestimated because features beyond the source query "
                                   "bbox were not requested; diagnostic, not a geological signal"),
                    "unit": "binary flag", "unit_basis": "computed flag", "type": "edge_limited_flag",
                    "role": "diagnostic", "source": source, "derived_from": name, **edge_info})
                col["edge_effect"] = edge_info
                if edge_info["n_cells_edge_limited"]:
                    log(f"{name}: {edge_info['n_cells_edge_limited']} cells may be edge-limited; "
                        "widen query_buffer_deg if this matters")
            col["sampling"] = {"method": "distance from cell centre to nearest feature", "n_features": len(geoms),
                               "predicate": predicate}
        elif ftype == "polygon_fraction":
            geoms, props, _ = vector(source)
            if predicate:
                geoms, props = gt.filter_features(geoms, props, lambda p: _match(p, predicate))
            if not geoms:
                log(f"{name}: predicate를 통과한 polygon이 0개라 열을 만들지 않는다")
                dropped.append({"feature": name, "reason": "0 matching polygons"})
                continue
            column, info = gt.polygon_fraction(spec, geoms, grid)
            col["sampling"] = {"property": feat["property"], "predicate": predicate, **info}
            col["unit"] = "fraction"
            col["unit_basis"] = "computed by the table builder from projected geometry"
        elif ftype == "line_density":
            geoms, props, _ = vector(source)
            if predicate:
                geoms, props = gt.filter_features(geoms, props, lambda p: _match(p, predicate))
            if not geoms:
                log(f"{name}: predicate를 통과한 line이 0개라 열을 만들지 않는다")
                dropped.append({"feature": name, "reason": "0 matching lines"})
                continue
            column, info = gt.line_density(spec, geoms, grid)
            col["sampling"] = {"predicate": predicate, **info}
            col["unit"] = "km/km2"
            col["unit_basis"] = "computed by the table builder from projected geometry"
        elif ftype == "polygon_attribute":
            geoms, props, _ = vector(source)
            if predicate:
                geoms, props = gt.filter_features(geoms, props, lambda p: _match(p, predicate))
            if len(geoms) == 0:
                log(f"{name}: AOI 안에 polygon이 0개라 열을 만들지 않는다")
                dropped.append({"feature": name, "reason": "0 polygons in AOI"})
                continue
            mapping = feat.get("mapping")
            raw_vals = [p.get(feat["property"]) for p in props]
            if mapping:
                vals = [mapping.get(str(v)) for v in raw_vals]
            else:
                vals = []
                for v in raw_vals:
                    try:
                        vals.append(float(v))
                    except (TypeError, ValueError):
                        vals.append(None)
            column, info = gt.attribute_at_centers(spec, geoms, vals, grid)
            col["sampling"] = {"method": "attribute of polygon containing cell centre (last match wins on overlap)",
                               "property": feat["property"], "predicate": predicate, "mapping": mapping, **info}
        elif ftype == "point_statistic":
            geoms, props, _ = vector(source)
            if predicate:
                geoms, props = gt.filter_features(geoms, props, lambda p: _match(p, predicate))
            pts, point_rule = _as_points(geoms, feat)
            raw_vals = []
            for p_ in props:
                try:
                    raw_vals.append(float(p_.get(feat["property"])))
                except (TypeError, ValueError):
                    raw_vals.append(None)
            if len(pts) == 0:
                log(f"{name}: AOI 안에 표본 point가 0개라 열을 만들지 않는다")
                dropped.append({"feature": name, "reason": "0 sample points in AOI after filter"})
                continue
            stat = feat.get("stat", "median")
            column, info = gt.point_statistic(spec, pts, raw_vals, stat=stat, grid=grid)
            info = {"method": f"per-cell {stat} of sample points (NaN where no sample)", "property": feat["property"],
                    "point_rule": point_rule, **info}
            if stat == "count":
                col["unit"] = feat.get("unit", "count")
                col["unit_basis"] = "computed count of records per cell"
            fill = feat.get("fill")
            if fill:
                column, support, finfo = gt.nearest_fill(spec, column, pts, raw_vals, float(fill["max_distance"]), grid=grid)
                info["fill"] = finfo
                extra_cols[f"{name}_support_distance"] = (support, {
                    "definition": f"Distance from cell centre to nearest valid sample used for {name}; survey-support diagnostic, not a geological signal",
                    "unit": spec.unit, "unit_basis": f"computed in the grid CRS {spec.crs}; axis unit {spec.unit}",
                    "type": "support_distance", "role": "diagnostic", "source": source, "derived_from": name})
            col["sampling"] = info
        elif ftype == "point_presence":
            geoms, props, _ = vector(source)
            n_total = len(geoms)
            if predicate:
                geoms, props = gt.filter_features(geoms, props, lambda p: _match(p, predicate))
            pts, point_rule = _as_points(geoms, feat)
            column, counts, pinfo = gt.presence_from_points(spec, pts, buffer=float(feat.get("buffer", 0)), grid=grid)
            integer_column = True
            col["unit"] = "record presence"
            col["unit_basis"] = "computed from the selected records"
            col["sampling"] = {"point_rule": point_rule, "n_features_total": n_total,
                               "n_features_after_filter": len(pts), **pinfo}
            col["absence_semantics"] = pinfo["absence_semantics"]
            extra_cols[f"{name}_count"] = (counts, {
                "definition": f"Number of selected records in the cell used for {name}",
                "unit": "count", "unit_basis": "computed count of records per cell", "type": "record_count",
                "role": "record_derived", "source": source, "derived_from": name,
                "absence_semantics": pinfo["absence_semantics"]})
        else:
            raise ValueError(f"알 수 없는 feature type: {ftype}")
        units[name] = col["unit"]
        columns[name] = col
        if integer_column:
            extra[name] = np.asarray(column).astype(int)
        else:
            values[name] = column
        for sname, (svalues, smeta) in extra_cols.items():
            smeta = {"source_sha256": col["source_sha256"], **smeta}
            if smeta["type"] == "record_count":
                extra[sname] = np.asarray(svalues).astype(int)
            else:
                values[sname] = svalues
            units[sname] = smeta["unit"]
            columns[sname] = smeta

    # 정확한 AOI 소속(셀 중심 역변환). 전체 격자는 보존하고 인계 표는 정책에 따라 고른다.
    in_aoi, dinfo = gt.aoi_mask(spec, recipe["aoi_wgs84"], grid=grid)
    extra["in_aoi"] = in_aoi.astype(int)
    columns["in_aoi"] = {"role": "mask", "unit": "binary flag", "unit_basis": "computed flag",
                         "definition": "1 if the cell centre lies inside the requested AOI (" + dinfo["method"] + "); 0 otherwise."}
    df = gt.assemble_table(spec, values, grid=grid, extra=extra)
    value_cols = [n for n, c in columns.items() if c.get("role") == "value"]
    presence_cols = [n for n, c in columns.items() if c.get("type") == "point_presence"]
    max_missing = (recipe.get("requirements") or {}).get("max_missing_fraction")
    report = gt.validate_table(df, spec, value_cols, presence_columns=presence_cols,
                               max_missing_fraction=max_missing)
    for dname, meta_ in columns.items():
        if meta_.get("role") in ("diagnostic", "record_derived") and dname not in presence_cols:
            if not pd.api.types.is_numeric_dtype(df[dname]):
                report["errors"].append(f"{meta_['role']} column not numeric: {dname}")
            elif df[dname].isna().all():
                report["warnings"].append(f"{meta_['role']} column all missing: {dname}")
    if dropped:
        report["errors"].append(f"requested columns missing: {[d['feature'] for d in dropped]}")
    report["ok"] = not report["errors"]
    out_dir = os.path.join(workspace, "table")
    name = recipe.get("output", {}).get("name", "grid_table")
    table = gt.write_table(df, out_dir, name=name)
    records_inside = {c: int(((df[c] == 1) & in_aoi).sum()) for c in presence_cols}
    records_outside = {c: int(((df[c] == 1) & ~in_aoi).sum()) for c in presence_cols}
    policy = (recipe.get("output") or {}).get("handoff", "aoi_centre")
    domain = {"mask_column": "in_aoi", **dinfo, "present_cells_inside": records_inside,
              "present_cells_outside": records_outside, "handoff_policy": policy,
              "note": ("Rows outside the AOI keep computed values. Sources were queried for the AOI (plus any query "
                       "buffer), so record-derived columns outside it are not evidence of no records. The full grid "
                       "and in_aoi mask preserve boundary-cell choices for later work.")}
    if bounds_method is not None:
        domain["grid_bounds_method"] = bounds_method
    if policy == "aoi_centre":
        handoff_df = df[in_aoi].reset_index(drop=True)
        handoff = gt.write_table(handoff_df, out_dir, name=f"{name}.in-aoi")
        handoff_report = gt.validate_table(handoff_df, spec, value_cols, presence_columns=presence_cols,
                                           require_full_grid=False, max_missing_fraction=max_missing)
        domain["handoff_table"] = {**handoff, "rows_excluded": int(len(df) - len(handoff_df)),
                                   "present_cells_excluded": records_outside, "validation": handoff_report}
        if handoff_report["errors"]:
            report["errors"].extend(f"handoff: {e}" for e in handoff_report["errors"])
            report["ok"] = False
    else:
        handoff = None
        domain["handoff_table"] = {**table, "note": "full grid handed off; rows outside AOI carry in_aoi=0"}
    meta = gt.build_metadata(spec, table, columns, report, provenance=index.records,
                             notes=recipe.get("notes", []), project=recipe.get("project", ""))
    meta["aoi_wgs84"] = recipe.get("aoi_wgs84")
    meta["domain"] = domain
    meta["dropped_features"] = dropped
    meta["source_completeness"] = source_completeness or {}
    for source_name, paging in (source_completeness or {}).items():
        if paging.get("completeness") != "complete":
            warning = paging.get("warning") or f"source {source_name} paging completeness is {paging.get('completeness', 'unknown')}"
            report["warnings"].append(f"source {source_name}: {warning}")
    meta["validation"] = report
    meta_path = gt.write_json(meta, os.path.join(out_dir, f"{name}.metadata.json"))
    boundary = gt.aoi_boundary_in_grid_crs(spec, recipe["aoi_wgs84"])
    shown = [n for n in columns if columns[n].get("role") == "value"] + presence_cols
    png = gt.preview_figure(spec, df, shown, os.path.join(out_dir, f"{name}.preview.png"),
                            marker_column=presence_cols[0] if presence_cols else None, units=units,
                            title=f"{recipe.get('project', name)} (acquisition preview)",
                            mask=in_aoi, boundary=boundary)
    summary = {"table": table, "metadata": meta_path, "preview": png, "handoff": handoff,
               "domain": {k: domain[k] for k in ("n_inside", "n_outside", "present_cells_inside",
                                                 "present_cells_outside", "handoff_policy")},
               "validation": report, "n_value_columns": len(value_cols),
               "n_diagnostics": sum(1 for c in columns.values() if c.get("role") == "diagnostic"),
               "record_columns": presence_cols, "source_completeness": source_completeness or {},
               "dropped_features": dropped}
    return summary, (0 if report["ok"] else 2)


# ---------------------------------------------------------------------------
def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--recipe", required=True)
    ap.add_argument("--workspace", required=True)
    ap.add_argument("--approve-hosts", action="store_true", help="현재 사용자의 승인을 --approved-by/--evidence 및 선택적 --approval-scope로 기록")
    ap.add_argument("--approve-disallowed", action="store_true",
                    help="이전 명령 호환용: 별도 robots 승인 gate 없음")
    ap.add_argument("--approve-unreadable-robots", action="store_true",
                    help="이전 명령 호환용: robots 읽기 실패는 유효한 승인을 막지 않음")
    ap.add_argument("--approved-by", default="")
    ap.add_argument("--approval-scope", default="", help="선택 항목: 현재 작업 식별자(기본: current workspace task; 절대 경로 금지)")
    ap.add_argument("--evidence", default="")
    ap.add_argument("--dry-run", action="store_true", help="승인 확인과 계획만 출력")
    ap.add_argument("--no-reuse", action="store_true", help="검증된 기존 파일이 있어도 다시 요청한다(기본은 요청 서명·sha256 일치 시 재사용)")
    args = ap.parse_args(argv)
    with open(args.recipe, encoding="utf-8") as fh:
        recipe = json.load(fh)
    problems = validate_recipe(recipe)
    if problems:
        print("recipe 오류(네트워크 접근 전 중단):\n  - " + "\n  - ".join(problems))
        return 1
    ws = os.path.abspath(args.workspace)
    raw_dir = os.path.join(ws, "raw")
    os.makedirs(raw_dir, exist_ok=True)
    b = recipe.get("budget", {})
    budget = fetch_budget.FetchBudget(delay=float(b.get("delay", 1.0)), max_requests=b.get("max_requests", 120),
                                      max_seconds=b.get("max_seconds"))
    state_path = os.path.join(ws, "acquisition-state.json")
    recipe_path = os.path.abspath(args.recipe)
    state = {"schema_version": 1, "project": recipe.get("project", ""),
             "recipe": recipe_path, "recipe_sha256": downloader.sha256_file(recipe_path),
             "started_at": now(), "hosts": {}, "downloads": {}, "table": None,
             "validation": None, "open_issues": [], "budget": None, "result_status": "in_progress"}

    def save_state():
        state["updated_at"] = now()
        state["budget"] = budget.snapshot()
        artifact_paths.dump_json(state, state_path)

    try:
        check_consent(recipe, ws, budget, args, report=state["hosts"])
    except fetch_budget.BudgetExceeded as exc:
        state["open_issues"].append(str(exc)); save_state(); return 3
    save_state()
    if any(v["status"].startswith("approval_required") for v in state["hosts"].values()):
        return 3
    if args.dry_run:
        result = {"hosts": state["hosts"], "sources": list(recipe["sources"]),
                  "features": [f["name"] for f in recipe["features"]]}
        print(json.dumps(artifact_paths.PathSerializer(os.path.join(ws, "stdout.json")).portable(result, stdout=True),
                         ensure_ascii=False, indent=2))
        return 0
    approved_hosts = set(state["hosts"])  # every host passed the consent check above
    index = downloader.ProvenanceIndex(os.path.join(ws, "provenance-index.json"))
    files: dict[str, list[str]] = {}
    source_statuses: dict[str, dict] = {}
    aoi = recipe.get("aoi_wgs84")
    reuse = not args.no_reuse
    for name, src in recipe["sources"].items():
        status: dict = {}
        try:
            t = src["type"]
            if t == "esri_query":
                files[name] = [fetch_esri_query(name, src, query_bbox(aoi, src), raw_dir, budget, index,
                                                reuse=reuse, status=status, allowed_hosts=approved_hosts)]
            elif t == "wfs_getfeature":
                files[name] = [fetch_wfs(name, src, query_bbox(aoi, src), raw_dir, budget, index,
                                         reuse=reuse, status=status, allowed_hosts=approved_hosts)]
            elif t == "wcs_getcoverage":
                files[name] = [fetch_wcs(name, src, aoi, raw_dir, budget, index, reuse=reuse, status=status,
                                         allowed_hosts=approved_hosts)]
            elif t == "file":
                files[name] = fetch_file(name, src, raw_dir, budget, index, reuse=reuse, status=status,
                                         allowed_hosts=approved_hosts)
            elif t == "local_file":
                files[name] = local_file(name, src, raw_dir, index)
            else:
                raise ValueError(f"알 수 없는 source type: {t}")
            source_statuses[name] = status
            paging = status.get("paging")
            incomplete = paging is not None and paging.get("completeness") != "complete"
            state["downloads"][name] = {"files": files[name], "status": "partial" if incomplete else "ok",
                                        "reused": bool(status.get("reused")),
                                        "request_signature": status.get("request_signature"), "paging": paging}
            if incomplete:
                state["open_issues"].append(f"source {name}: {paging.get('warning') or 'paging completeness not established'}")
        except fetch_budget.BudgetExceeded as exc:
            state["downloads"][name] = {"files": [], "status": "stopped", "error": str(exc)}
            state["open_issues"].append(f"source {name}: {exc}")
            save_state()
            return 3
        except (downloader.DownloadError, FileNotFoundError, ValueError) as exc:
            log(f"{name}: FAILED {exc}")
            state["downloads"][name] = {"files": [], "status": "failed", "error": str(exc)}
            state["open_issues"].append(f"source {name}: {exc}")
            if isinstance(exc, downloader.DownloadError) and exc.status in (401, 403):
                save_state()
                return 3
        save_state()
    skipped = [f["name"] for f in recipe["features"] if not files.get(f["source"])]
    if skipped:
        state["open_issues"].append(f"source 실패로 제외한 feature: {skipped}")
        recipe = dict(recipe, features=[f for f in recipe["features"] if files.get(f["source"])])
        log(f"제외한 feature: {skipped}")
    if not recipe["features"]:
        state["open_issues"].append("사용 가능한 feature가 없다")
        state["result_status"] = "partial"
        save_state()
        return 2
    source_completeness = {name: data["paging"] for name, data in source_statuses.items()
                           if data.get("paging") is not None}
    summary, code = build_table(recipe, files, ws, index, source_completeness=source_completeness)
    if skipped:
        summary["validation"]["errors"].append(f"requested columns failed: {skipped}")
        summary["validation"]["ok"] = False
        code = 2
        with open(summary["metadata"], encoding="utf-8") as fh:
            meta = json.load(fh)
        meta["validation"] = summary["validation"]
        artifact_paths.dump_json(meta, summary["metadata"])
    summary["skipped_features"] = skipped
    state["table"] = {k: summary[k] for k in ("table", "metadata", "preview", "handoff")}
    state["domain"] = summary["domain"]
    state["validation"] = summary["validation"]
    state["record_columns"] = summary["record_columns"]
    incomplete_sources = {n: p for n, p in source_completeness.items() if p.get("completeness") != "complete"}
    state["source_completeness"] = source_completeness
    if incomplete_sources:
        state["result_status"] = "partial"
        code = max(code, 2)
        for source_name, paging in incomplete_sources.items():
            issue = f"source {source_name}: {paging.get('warning') or 'paging completeness not established'}"
            if issue not in state["open_issues"]:
                state["open_issues"].append(issue)
    else:
        state["result_status"] = "complete" if code == 0 else "partial"
    for d in summary.get("dropped_features", []):
        state["open_issues"].append(f"feature {d['feature']} dropped: {d['reason']}")
    save_state()
    output = {"result": state["result_status"], "table": summary["table"]["path"],
                      "handoff": (summary["handoff"] or {}).get("path"), "domain": summary["domain"],
                      "rows": summary["table"]["rows"], "n_value_columns": summary["n_value_columns"],
                      "n_diagnostics": summary["n_diagnostics"],
                      "reused_sources": [n for n, d in state["downloads"].items() if d.get("reused")],
                      "present_cells": summary["validation"]["summary"].get("present_cells"),
                      "warnings": summary["validation"]["warnings"], "errors": summary["validation"]["errors"],
                      "source_completeness": source_completeness,
                      "skipped_features": summary.get("skipped_features", []),
                      "dropped_features": summary.get("dropped_features", []),
                      "requests": budget.snapshot(), "state": state_path}
    print(json.dumps(artifact_paths.PathSerializer(os.path.join(ws, "stdout.json")).portable(output, stdout=True),
                     ensure_ascii=False, indent=2, default=str))
    return code


if __name__ == "__main__":
    raise SystemExit(main())
